/**
 * Admin seeding tool for ambient barks (build plan M31, npc-runtime.md §9.1, architecture §6.3).
 * Only this tool writes the shared `cache/*`: it publishes each villager's solo lines per activity
 * as `cache/lines/{sha256(soloBarkSeedMaterial(npcId, activity, lang, index))}` and each related
 * pair's exchanges as two lines `cache/lines/{sha256(exchangeSeedMaterial(a, b, lang, index, 0|1))}`,
 * with their translations by native language. A line the file lacks is generated by the client
 * for that player alone (hybrid task `ambientBarks`, cloud first) and kept in its IndexedDB.
 *
 *   npm run seed:ambient -- --prompts <lang> [<nativeLang>]           print the generation prompts
 *   npm run seed:ambient -- <ambient.json>                            dry run: validate, list gaps
 *   npm run seed:ambient -- <ambient.json> --write --project <id>     publish (admin credentials)
 *
 * The file: `{ "lang": "es",
 *   "solo": { "<npcId>": { "<activity>": [line, …] } },
 *   "exchanges": { "<a>+<b>": [[line, line], …] } }`, a line being `{ "text", "reading"?, "translation": { "en": "…" } }`.
 * Run the printed prompts through the cloud model (`gemini-3.8-flash`) with the `ambientBarks`
 * JSON schema, spot-check the lines and convert them before writing.
 *
 * TODO(seeding tool, no milestone yet, see pending.md): run the prompts from here with the admin
 * project, and voice the lines (seeded `tts/` clips).
 */
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { z } from "zod";
import {
  AMBIENT_BARKS_PER_SET,
  AMBIENT_EXCHANGES_PER_PAIR,
  ambientBarksPrompt,
  ambientPromptInput,
  BARK_PAIRS,
  barkActivities,
  type CachedLine,
  CachedLineSchema,
  exchangeSeedMaterial,
  FirestorePaths,
  getLanguage,
  isNpcId,
  NPC_IDS,
  type NpcActivity,
  type NpcId,
  soloBarkSeedMaterial,
} from "../../packages/shared/src/index";

export const AmbientFileSchema = z.strictObject({
  lang: z.string().min(2).max(20),
  solo: z.record(z.string(), z.record(z.string(), z.array(CachedLineSchema).max(AMBIENT_BARKS_PER_SET))).default({}),
  exchanges: z.record(z.string(), z.array(z.tuple([CachedLineSchema, CachedLineSchema])).max(AMBIENT_EXCHANGES_PER_PAIR)).default({}),
});

export interface AmbientPlan {
  lang: string;
  docs: { path: string; doc: CachedLine }[];
  /** Sets the file does not cover (generated per player on a miss). */
  missing: string[];
}

export const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");

const linePath = (material: string) => FirestorePaths.cacheEntry("lines", sha256(material));

export function planAmbientSeed(raw: unknown): AmbientPlan {
  const file = AmbientFileSchema.parse(raw);
  if (!getLanguage(file.lang)) throw new Error(`unknown language: ${file.lang}`);
  const docs: AmbientPlan["docs"] = [];
  for (const [npcId, sets] of Object.entries(file.solo)) {
    if (!isNpcId(npcId)) throw new Error(`unknown NPC: ${npcId}`);
    const activities = barkActivities(npcId);
    for (const [activity, lines] of Object.entries(sets)) {
      if (!activities.includes(activity as NpcActivity)) throw new Error(`the ${npcId} has no "${activity}" in their schedule`);
      lines.forEach((doc, i) => docs.push({ path: linePath(soloBarkSeedMaterial(npcId, activity as NpcActivity, file.lang, i)), doc }));
    }
  }
  for (const [key, exchanges] of Object.entries(file.exchanges)) {
    const pair = BARK_PAIRS.find((p) => `${p.a}+${p.b}` === key);
    if (!pair) throw new Error(`not a relationship pair (a+b in NPC doc order): ${key}`);
    exchanges.forEach(([first, second], i) => {
      docs.push({ path: linePath(exchangeSeedMaterial(pair.a, pair.b, file.lang, i, 0)), doc: first });
      docs.push({ path: linePath(exchangeSeedMaterial(pair.a, pair.b, file.lang, i, 1)), doc: second });
    });
  }
  const missing: string[] = [];
  for (const npcId of NPC_IDS) for (const activity of barkActivities(npcId)) if ((file.solo[npcId]?.[activity]?.length ?? 0) < AMBIENT_BARKS_PER_SET) missing.push(`${npcId}/${activity}`);
  for (const p of BARK_PAIRS) if ((file.exchanges[`${p.a}+${p.b}`]?.length ?? 0) < AMBIENT_EXCHANGES_PER_PAIR) missing.push(`${p.a}+${p.b}`);
  return { lang: file.lang, docs, missing };
}

/** One prompt per villager × activity, and one per relationship pair. */
export function ambientPrompts(lang: string, nativeLang = "en"): { key: string; prompt: string }[] {
  if (!getLanguage(lang)) throw new Error(`unknown language: ${lang}`);
  if (!getLanguage(nativeLang)) throw new Error(`unknown language: ${nativeLang}`);
  const out: { key: string; prompt: string }[] = [];
  for (const npcId of NPC_IDS as readonly NpcId[]) {
    for (const activity of barkActivities(npcId)) out.push({ key: `${npcId}/${activity}`, prompt: ambientBarksPrompt(ambientPromptInput({ kind: "solo", npcId, activity, index: 0 }, lang, nativeLang)) });
  }
  for (const p of BARK_PAIRS) out.push({ key: `${p.a}+${p.b}`, prompt: ambientBarksPrompt(ambientPromptInput({ kind: "exchange", a: p.a, b: p.b, index: 0 }, lang, nativeLang)) });
  return out;
}

export async function writeAmbientSeed(plan: AmbientPlan, projectId: string): Promise<void> {
  const { initializeApp, applicationDefault } = await import("firebase-admin/app");
  const { getFirestore } = await import("firebase-admin/firestore");
  const emulated = Boolean(process.env.FIRESTORE_EMULATOR_HOST);
  const app = initializeApp(emulated ? { projectId } : { projectId, credential: applicationDefault() }, "hellovalley-seed-ambient");
  const db = getFirestore(app);
  await Promise.all(plan.docs.map((d) => db.doc(d.path).set(d.doc)));
  console.log(`seeded ${plan.docs.length} ambient lines for ${plan.lang}`);
}

function arg(args: readonly string[], name: string): string | undefined {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : undefined;
}

export async function main(args: readonly string[]): Promise<number> {
  const promptsFor = arg(args, "--prompts");
  if (promptsFor) {
    const native = args[args.indexOf("--prompts") + 2];
    for (const p of ambientPrompts(promptsFor, native && !native.startsWith("--") ? native : "en")) console.log(`--- ${p.key}\n${p.prompt}\n`);
    return 0;
  }
  const path = args[0];
  if (!path || path.startsWith("--")) {
    console.error("usage: seed-ambient --prompts <lang> [<nativeLang>] | <ambient.json> [--write --project <id>]");
    return 2;
  }
  const plan = planAmbientSeed(JSON.parse(await readFile(path, "utf8")));
  console.log(`${plan.lang}: ${plan.docs.length} ambient lines, ${plan.missing.length} sets incomplete${plan.missing.length ? ` (${plan.missing.join(", ")})` : ""}`);
  if (!args.includes("--write")) {
    console.log("dry run: nothing written (add --write --project <id>)");
    return 0;
  }
  const projectId = arg(args, "--project");
  if (!projectId) {
    console.error("--write needs --project <id>");
    return 2;
  }
  if (!process.env.FIRESTORE_EMULATOR_HOST && !process.env.GOOGLE_APPLICATION_CREDENTIALS) {
    console.error("--write needs GOOGLE_APPLICATION_CREDENTIALS (an admin service account) or the emulators");
    return 2;
  }
  await writeAmbientSeed(plan, projectId);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main(process.argv.slice(2)).then(
    (code) => process.exit(code),
    (error: unknown) => {
      console.error(error instanceof Error ? error.message : error);
      process.exit(1);
    },
  );
}
